# The conformance suite is fetched and built outside this runner (its
# sources are not in the repository): without its results the two are
# skipped, as tests/run_vulkan.sh skips what needs lavapipe.
if [[ -f mlx-out/cts/results/framework.txt ]]; then
    run 521_cts_framework_runtime "the Vulkan conformance suite's framework built by our toolchain from the sources at vulkan-cts-1.3.10.0 (delibs and qphelper by mlx-cc, linked by mlx-ld on mlxlibc and mlxlibcpp, no other compiler's object in it) and its 33 self-tests run, each ok: debase, depool, dethread, deutil, decpp, a test log written and read back"
else
    echo "skip 521_cts_framework_runtime (no mlx-out/cts/results/framework.txt: tools/fetch_cts.sh, then tools/check_cts.sh --framework)"
fi
if [[ -f mlx-out/cts/results/check-cases.qpa ]]; then
    run 522_cts_cases_runtime "the conformance suite's cases of projects/cts/check-cases.txt (info, device_init, object_management.single, memory.allocation.basic, api.buffer, synchronization.basic: what the driver's stage has) passed by our driver over the host card, each once with Pass in the suite's result file, its result ended, no other case beside them, every run the port's tag against our driver; the reading held against made-up result files (a crash before a pass, a run cut off, another library, another release) and tools/run_cts.sh against a stand-in suite (a crash, a case not run, not supported for want of the port, a command the port could not give)"
else
    echo "skip 522_cts_cases_runtime (no mlx-out/cts/results/check-cases.qpa: tools/fetch_cts.sh, then tools/check_cts.sh)"
fi

# The same program static (object/elf64.mlx's image).
status=0
if "$compiler" --quiet tests/support/zero_data_static.mlx -o "$work/zero_data_static"; then
    "$work/zero_data_static" || status=$?
    if [[ $status -eq 13 ]]; then
        echo "ok   zero_data_static: a static program's globals that start zero in its .bss, in memory only"
    else
        echo "FAIL zero_data_static: check $status failed"
        failures=$((failures + 1))
    fi
else
    echo "FAIL zero_data_static did not compile"
    failures=$((failures + 1))
fi

# The headers of what test 512 cannot run here (tests/support/
# zero_data_headers.mlx, exits 13): the same programs for brixOS, a
# versioned plugin whose export var starts zero (its data symbols in
# .data and .bss, the version sections named after .bss), and a
# freestanding program, which keeps every global in its file.
headers() {
    local label=$1 least=$2 words=$3
    shift 3
    local status=0
    if ! "$compiler" --quiet "$@" -o "$work/zero_data_$label"; then
        echo "FAIL zero_data_headers_$label did not compile"
        failures=$((failures + 1))
        return
    fi
    "$work/zero_data_headers" "$work/zero_data_$label" "$least" || status=$?
    if [[ $status -eq 13 ]]; then
        echo "ok   zero_data_headers_$label: $words"
    else
        echo "FAIL zero_data_headers_$label: check $status failed"
        failures=$((failures + 1))
    fi
}
if "$compiler" --quiet tests/support/zero_data_headers.mlx -o "$work/zero_data_headers"; then
    headers brixos_static 4194304 "a static brixOS program's globals that start zero in its .bss" --target=x86_64-brixos tests/support/zero_data_static.mlx
    headers brixos_linked 4194304 "a linked brixOS program's globals that start zero in its .bss" --target=x86_64-brixos tests/512_zero_data_runtime.mlx
    headers plugin 8 "a versioned plugin's export var that starts zero a data symbol in its .bss, its sections named" --plugin --soname=libzero.so.1 --symbol-version=ZERO_1 tests/support/plugin_library.mlx
    headers freestanding none "a freestanding program keeps every global in its file: no .bss" --target=x86_64-freestanding tests/support/zero_data_freestanding.mlx
else
    echo "FAIL zero_data_headers did not compile"
    failures=$((failures + 1))
fi

# A packed struct wider than a word is refused with the message that says
# so (tests/support/packed_too_wide).
too_wide=$("$compiler" --quiet tests/support/packed_too_wide/main.mlx -o "$work/too_wide" 2>&1 || true)
if grep -q 'MLX-E4001: a packed struct holds at most 64 bits' <<< "$too_wide"; then
    echo "ok   packed_too_wide: a packed struct of 80 bits refused"
else
    echo "FAIL packed_too_wide: expected the 64-bit message, got:"
    echo "$too_wide" | head -3
    failures=$((failures + 1))
fi

if [[ $failures -ne 0 ]]; then
    echo "$failures standard module checks failed"
    exit 1
fi
echo "all standard module checks passed"
